class Solution:
    def canAttendMeetings(self, intervals: List[Interval]) -> bool:
        #receive a list of intervals
        #return a boolean if can attend all meetings, else False
        #ex: 

        #sort by start time
        #check through each interval
        #if end time >= start time, return False
        #after checking all intervals, can return True

        intervals.sort(key=lambda x:x.start)

        for i in range(1, len(intervals)):
            current = intervals[i]
            previous = intervals[i - 1]
            if previous.end > current.start:
                return False
        return True

class Solution:
    def islandPerimeter(self, grid: List[List[int]]) -> int:
        
        visited = set()

        for row in range(len(grid)):
            for col in range(len(grid[0])):
                if grid[row][col] == 1:
                    return self.dfs(grid, row, col, visited)
        

    def dfs(self, grid, row, col, visited):
        if row < 0 or row >= len(grid) or col < 0 or col >= len(grid[0]) or grid[row][col] == 0:
            return 1
        
        if (row, col) in visited:
            return 0
        
        visited.add((row, col))

        return (
            self.dfs(grid, row + 1, col, visited) + 
            self.dfs(grid, row -1, col, visited) +
            self.dfs(grid, row, col + 1, visited) +
            self.dfs(grid, row, col - 1, visited)
        )

